package com.shici.app.core.b3
import com.shici.app.core.*
import org.junit.Assert.*
import org.junit.Test
class B3SessionGateAcceptanceTest {
 private val payload=LearningBackupCodec.decode(LearningBackupCodec.encode(LearningBackupData(emptyList(),emptyList()),"v",10,0))
 private fun preview(s:LearningRestoreSession):Int{val id=s.beginImport()!!;assertTrue(s.beginReading(id,"content://input"));assertTrue(s.freezeImport(id,payload));return id}
 @Test fun restoreRequiresOrderedPhasesAndExactIds(){val s=LearningRestoreSession();assertNull(s.confirm());assertNull(s.beginApply(7));val id=s.beginImport()!!;assertNull(s.beginImport());assertFalse(s.freezeImport(id,payload));assertFalse(s.beginReading(id+1,"bad"));assertTrue(s.beginReading(id,"source"));assertFalse(s.beginReading(id,"source"));assertTrue(s.freezeImport(id,payload));assertFalse(s.freezeImport(id,payload));val safety=s.confirm()!!;assertNotEquals(id,safety);assertNull(s.confirm());assertNull(s.beginApply(id));assertSame(payload,s.beginApply(safety));assertNull(s.beginApply(safety));assertTrue(s.finish(safety));assertFalse(s.busy);assertFalse(s.finish(safety))}
 @Test fun lateImportCannotConsumeNewRequest(){val s=LearningRestoreSession();val old=s.beginImport()!!;s.cancelImport(old);val now=s.beginImport()!!;assertFalse(s.beginReading(old,"bad"));assertFalse(s.cancelImport(old));assertEquals(now,s.importRequestCode)}
 @Test fun oldSafetyCannotApplyNewPayload(){val s=LearningRestoreSession();preview(s);val old=s.confirm()!!;s.cancelSafety(old);preview(s);val now=s.confirm()!!;assertNull(s.beginApply(old));assertFalse(s.cancelSafety(old));assertSame(payload,s.beginApply(now))}
 @Test fun clearDiscardsFrozenPayloadAndOldCallbacks(){val s=LearningRestoreSession();preview(s);val id=s.confirm()!!;s.clear();assertNull(s.beginApply(id));assertFalse(s.finish(id));assertFalse(s.busy)}
 @Test fun stopPreservesBothSystemPickers(){val s=LearningRestoreSession();s.beginImport();assertFalse(s.cancelPreparation());assertTrue(s.busy);s.clear();preview(s);val id=s.confirm();assertFalse(s.cancelPreparation());assertEquals(id,s.safetyRequestCode)}
 @Test fun stopCancelsReadingAndPreviewButNotApplying(){val s=LearningRestoreSession();val i=s.beginImport()!!;s.beginReading(i,"uri");assertTrue(s.cancelPreparation());assertFalse(s.freezeImport(i,payload));preview(s);assertTrue(s.cancelPreparation());preview(s);val a=s.confirm()!!;s.beginApply(a);assertFalse(s.cancelPreparation());assertTrue(s.finish(a))}
 @Test fun allCancelPathsCanRestart(){val s=LearningRestoreSession();val i=s.beginImport()!!;assertTrue(s.cancelImport(i));preview(s);assertTrue(s.cancelPreview());preview(s);val a=s.confirm()!!;assertTrue(s.cancelSafety(a));assertNotNull(s.beginImport())}
 @Test fun backupExportFreezeOnceAndCallbackOnce(){val s=LearningBackupExportSession();val i=s.begin()!!;assertNull(s.begin());assertFalse(s.freeze(i+1,byteArrayOf(0)));val bytes=byteArrayOf(1,2);assertTrue(s.freeze(i,bytes));assertFalse(s.cancelPreparation());assertNull(s.takeResult(i+1));assertSame(bytes,s.takeResult(i));assertNull(s.takeResult(i));assertTrue(s.cancel(i));assertNotNull(s.begin())}
 @Test fun backupStopDuringLoadingIgnoresOldFreeze(){val s=LearningBackupExportSession();val old=s.begin()!!;assertTrue(s.cancelPreparation());val now=s.begin()!!;assertFalse(s.freeze(old,byteArrayOf(0)));assertFalse(s.cancel(old));assertTrue(s.freeze(now,byteArrayOf(1)))}
 @Test fun pdfBackupRestoreShareUniqueAllocatorAndRespectReservation(){LearningExportSession.reserveRequestCode(20000);val pdf=LearningExportSession().begin("")!!.id;val backup=LearningBackupExportSession().begin()!!;val r=LearningRestoreSession();val imp=preview(r);val safety=r.confirm()!!;assertTrue(pdf>20000);assertEquals(4,setOf(pdf,backup,imp,safety).size)}
 @Test fun restoreBarrierStalesEveryOldKeyAndAllCredentialEpochs(){val g=DeletionGate();val first=g.capture();g.recordDeletion("one");val second=g.capture();assertFalse(g.isStale("other",first));g.recordRestore();for(k in listOf("one","other","not-in-backup","")){assertTrue(g.isStale(k,first));assertTrue(g.isStale(k,second));assertFalse(g.isStale(k,g.capture()))}}
 @Test fun repeatedRestoreAndKeyDeletionRemainIsolated(){val g=DeletionGate();g.recordRestore();val c=g.capture();g.recordDeletion("a");assertTrue(g.isStale("a",c));assertFalse(g.isStale("b",c));val n=g.capture();g.recordRestore();assertTrue(g.isStale("b",n));assertFalse(g.isStale("a",g.capture()))}
}
